#!/usr/bin/env python3
import json

L = [71,97,54,56,44,158,45,58,82,135,113,117,86,40,12,185,63,50,111,72,90,109,61,13,92,60,91,35,114,94,105,26,15,51,102,118,76,32,108,23,22,134,83,43,64]

index = {v:i for i,v in enumerate(L)}
N = len(L)
full_mask = (1 << N) - 1

Lset = set(L)
triples = []
triple_masks = []
for i in range(N):
    a = L[i]
    for j in range(i+1, N):
        b = L[j]
        s = a + b
        if s in Lset and s != a and s != b:
            triples.append((a,b,s))
            mask = (1<<i) | (1<<j) | (1<<index[s])
            triple_masks.append(mask)

num_to_triples = {v: [] for v in L}
for ti, (a,b,c) in enumerate(triples):
    num_to_triples[a].append(ti)
    num_to_triples[b].append(ti)
    num_to_triples[c].append(ti)

def search(used_mask, chosen):
    if used_mask == full_mask:
        return chosen
    best_num = None
    best_opts = None
    for num in L:
        bit = 1 << index[num]
        if used_mask & bit:
            continue
        opts = []
        for ti in num_to_triples[num]:
            if triple_masks[ti] & used_mask == 0:
                opts.append(ti)
        if not opts:
            return None
        if best_opts is None or len(opts) < len(best_opts):
            best_opts = opts
            best_num = num
            if len(opts) == 1:
                break
    for ti in best_opts:
        res = search(used_mask | triple_masks[ti], chosen + [triples[ti]])
        if res is not None:
            return res
    return None

solution = search(0, [])
if solution is None:
    witness = {"polarity":"negative","basis":"search","search_exhausted":True}
else:
    witness = {"polarity":"positive","solution":solution}
print("WITNESS: " + json.dumps(witness, ensure_ascii=False))
